                    for (const g of plan.groups) {
                        const where = g.center ? ' near ' + MM.geo.describePlace(g.center) : '';
                        lines.push('      ' + (g.choice === 'a' ? g.effects.a : g.effects.b) + where + ' (Map ' + g.choice.toUpperCase() + ')');
                    }
